:root {
  --bg: #1e1b2e;
  --card: #2d2a4a;
  --accent: #f7c948;
  --text: #f0eef8;
  --muted: #a09cb5;
  --correct: #6fcf97;
  --wrong: #eb5757;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 18px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  box-shadow: 8px 8px 0 #000;
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
  text-align: center;
  image-rendering: pixelated;
}

h1 {
  font-size: 2rem;
  margin: 0 0 24px;
  letter-spacing: 1px;
  text-shadow: 2px 2px 0 #000;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

.answer, .control {
  font-family: inherit;
  font-size: 1.25rem;
  padding: 14px 24px;
  border: 3px solid var(--accent);
  border-radius: 0;
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
  transition: transform 0.05s, box-shadow 0.05s, background 0.1s;
  box-shadow: 4px 4px 0 #000;
  min-width: 72px;
}

.answer:hover:not(:disabled), .control:hover:not(:disabled) {
  background: #3a3660;
  transform: translate(-1px, -1px);
  box-shadow: 5px 5px 0 #000;
}

.answer:focus-visible, .control:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.answer:active:not(:disabled), .control:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 #000;
}

.answer:disabled, .control:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  box-shadow: 2px 2px 0 #000;
}

.answer.correct { background: var(--correct); color: #000; }
.answer.wrong { background: var(--wrong); color: #fff; }

.score-line {
  font-size: 1.1rem;
  margin: 0 0 20px;
  color: var(--muted);
}

#score { color: var(--accent); font-weight: bold; }

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  h1 { font-size: 1.6rem; }
  .answer, .control { font-size: 1.1rem; padding: 12px 18px; }
}

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

let currentIndex = 0;
let score = 0;
let locked = false;
let finished = false;

function renderQuestion() {
  const q = questions[currentIndex];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  answerA.classList.remove('correct', 'wrong');
  answerB.classList.remove('correct', 'wrong');
  nextBtn.disabled = true;
  locked = false;
  finished = false;
}

function updateScore() {
  scoreEl.textContent = score;
}

function handleAnswer(choice) {
  if (locked || finished) return;
  locked = true;
  const q = questions[currentIndex];
  const isCorrect = choice === q.correct;
  if (isCorrect) {
    score += 1;
    updateScore();
  }
  const chosenBtn = choice === 'a' ? answerA : answerB;
  chosenBtn.classList.add(isCorrect ? 'correct' : 'wrong');
  answerA.disabled = true;
  answerB.disabled = true;
  nextBtn.disabled = false;
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (finished) return;
  if (currentIndex < questions.length - 1) {
    currentIndex += 1;
    renderQuestion();
  } else {
    finished = true;
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
    nextBtn.disabled = true;
  }
});

restartBtn.addEventListener('click', () => {
  currentIndex = 0;
  score = 0;
  updateScore();
  renderQuestion();
});

renderQuestion();
updateScore();
